// The "Weather" tab -- today/tomorrow's forecast, any active or
// predicted inclement event, and preparing/repairing your home against
// it (mirrors `/weather forecast` and `/housing prepare|repair`,
// `panem_shared.weather`). Forecasts/events are generated by `panem_bot.
// cogs.weather`'s own background poll -- this tab only ever reads what
// that poll has already written.
import { dropdown, el, setStatusText } from "./_shared.js?v=7";

// Only the category 1-6 kinds can be prepared against -- plain rain/snow
// carry no severity and nothing to board up for, same list `panem_bot.
// cogs.housing`'s own `/housing prepare` hardcodes.
const PREPARABLE_KINDS = [
  "thunderstorm",
  "hailstorm",
  "blizzard",
  "flash_flood",
  "heatwave",
  "windstorm",
];

function label(kind) {
  return kind
    .split("_")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
}

function forecastRow(dayLabel, forecast) {
  return el(
    "div",
    { class: "field-row" },
    el("label", { text: dayLabel }),
    el(
      "span",
      { class: "tab-status" },
      `${label(forecast.condition)}, ${forecast.temp_low}°-${forecast.temp_high}°`
    )
  );
}

function eventPanel(title, event_) {
  return el(
    "div",
    { class: "panel" },
    el("h2", { text: title }),
    el(
      "p",
      { class: "tab-status" },
      `${label(event_.kind)} -- category ${event_.severity}.` +
        (event_.status === "active"
          ? ` Expected to pass around tick ${event_.actual_end_tick}. Take cover if you're outside.`
          : ` Predicted to start around tick ${event_.predicted_start_tick}.`)
    )
  );
}

function propertyPanel(ctx, property_, resultLine, onChanged) {
  const kindSelect = dropdown(PREPARABLE_KINDS.map((k) => ({ value: k, label: label(k) })));
  const prepareBtn = el("button", { class: "btn", type: "button" }, "Prepare");
  prepareBtn.addEventListener("click", async () => {
    resultLine.textContent = "";
    try {
      const result = await ctx.apiFetch(
        `/activity/dashboard/weather/${ctx.characterId()}/prepare`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ discord_id: ctx.discordId(), kind: kindSelect.value }),
        }
      );
      resultLine.className = "result-line win";
      resultLine.textContent = `Prepared against ${label(result.kind)} (level ${result.level}).`;
      onChanged();
    } catch (err) {
      resultLine.className = "result-line lose";
      resultLine.textContent = err.message;
    }
  });

  const pointsInput = el("input", { type: "number", placeholder: "points", min: "1" });
  const repairBtn = el("button", { class: "btn secondary", type: "button" }, "Repair");
  repairBtn.addEventListener("click", async () => {
    resultLine.textContent = "";
    try {
      const result = await ctx.apiFetch(`/activity/dashboard/weather/${ctx.characterId()}/repair`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          discord_id: ctx.discordId(),
          points: Number(pointsInput.value || 0),
        }),
      });
      resultLine.className = "result-line win";
      resultLine.textContent = `Repaired ${result.points} points for ${result.cost} money.`;
      onChanged();
    } catch (err) {
      resultLine.className = "result-line lose";
      resultLine.textContent = err.message;
    }
  });

  const prepEntries = Object.entries(property_.prep);
  return el(
    "div",
    { class: "panel" },
    el("h2", { text: `Property -- ${property_.kind}` }),
    el("p", { class: "tab-status" }, `Damage: ${property_.damage_level}/100.`),
    el(
      "p",
      { class: "tab-status" },
      prepEntries.length
        ? `Prepared: ${prepEntries.map(([k, v]) => `${label(k)} (level ${v})`).join(", ")}.`
        : "Not prepared for anything yet."
    ),
    el("div", { class: "field-row" }, el("label", { text: "Prepare for" }), kindSelect, prepareBtn),
    el("div", { class: "field-row" }, el("label", { text: "Repair" }), pointsInput, repairBtn)
  );
}

export function mount(root, ctx) {
  const statusLine = el("p", { class: "tab-status" });
  const resultLine = el("p", { class: "result-line" });
  const host = el("div", {});
  root.append(statusLine, host, resultLine);

  async function refresh() {
    const characterId = ctx.characterId();
    const discordId = ctx.discordId();
    host.innerHTML = "";
    if (!characterId || !discordId) {
      setStatusText(statusLine, "Pick a character above first.");
      return;
    }
    try {
      const status = await ctx.apiFetch(
        `/activity/dashboard/weather/${characterId}/status?discord_id=${encodeURIComponent(discordId)}`
      );
      setStatusText(statusLine, "");

      const panels = [
        el(
          "div",
          { class: "panel" },
          el("h2", { text: `${ctx.districtName(status.district_id)} Forecast` }),
          status.today ? forecastRow("Today", status.today) : null,
          status.tomorrow ? forecastRow("Tomorrow", status.tomorrow) : null,
          !status.today && !status.tomorrow
            ? el("p", { class: "tab-status" }, "No forecast on file yet.")
            : null
        ),
        status.active_event ? eventPanel("Happening Now", status.active_event) : null,
        status.upcoming_event ? eventPanel("Predicted", status.upcoming_event) : null,
        status.property
          ? propertyPanel(ctx, status.property, resultLine, refresh)
          : el(
              "div",
              { class: "panel" },
              el("h2", { text: "Property" }),
              el("p", { class: "tab-status" }, "You don't own or lease a property to prepare/repair.")
            ),
      ].filter(Boolean);
      host.append(...panels);
    } catch (err) {
      setStatusText(statusLine, `Could not load weather: ${err.message}`, { error: true });
    }
  }

  refresh();

  return {};
}
